#include "rookforge/notation.hpp"
#include <algorithm>
#include <cctype>
#include <cstdlib>
#include <algorithm>
#include <sstream>
#include <stdexcept>
namespace rookforge {
namespace {
char letter(Piece p){switch(p){case Piece::King:return 'K';case Piece::Queen:return 'Q';case Piece::Rook:return 'R';case Piece::Bishop:return 'B';case Piece::Knight:return 'N';default:return ' ';}}
}
Move parseUci(const Board& b,const std::string& t){if(t.size()!=4&&t.size()!=5)throw std::invalid_argument("UCI move must have four or five characters");Move candidate{Board::square(t.substr(0,2)),Board::square(t.substr(2,2)),Piece::Empty};if(t.size()==5){switch(static_cast<char>(std::tolower(static_cast<unsigned char>(t[4])))){case 'q':candidate.promotion=Piece::Queen;break;case 'r':candidate.promotion=Piece::Rook;break;case 'b':candidate.promotion=Piece::Bishop;break;case 'n':candidate.promotion=Piece::Knight;break;default:throw std::invalid_argument("Invalid UCI promotion piece");}}for(auto m:b.legalMoves())if(m==candidate)return m;throw std::invalid_argument("Illegal UCI move: "+t);}
std::string san(const Board& b,Move m){auto legal=b.legalMoves();if(std::find(legal.begin(),legal.end(),m)==legal.end())throw std::invalid_argument("Cannot format an illegal move as SAN");int raw=static_cast<int>(b.at(m.from));Piece p=static_cast<Piece>(raw<0?-raw:raw);std::string out;if(p==Piece::King&&std::abs(m.to-m.from)==2)out=m.to>m.from?"O-O":"O-O-O";else{if(p!=Piece::Pawn)out+=letter(p);bool capture=b.at(m.to)!=Piece::Empty||(p==Piece::Pawn&&m.from%8!=m.to%8);if(p!=Piece::Pawn){bool sameFile=false,sameRank=false,ambiguous=false;for(auto x:legal)if(x.to==m.to&&x.from!=m.from&&b.at(x.from)==b.at(m.from)){ambiguous=true;sameFile|=m.from%8==x.from%8;sameRank|=m.from/8==x.from/8;}if(ambiguous){if(!sameFile)out+=static_cast<char>('a'+m.from%8);else if(!sameRank)out+=static_cast<char>('1'+m.from/8);else out+=Board::squareName(m.from);}}else if(capture)out+=static_cast<char>('a'+m.from%8);if(capture)out+='x';out+=Board::squareName(m.to);if(m.promotion!=Piece::Empty){out+='=';out+=letter(m.promotion);}}
 Board next=b;Undo u;next.makeMove(m,u);auto replies=next.legalMoves();if(next.inCheck(next.turn()))out+=replies.empty()?'#':'+';return out;}
Move parseSan(const Board& b,const std::string& token){std::string wanted=token;while(!wanted.empty()&&(wanted.back()=='!'||wanted.back()=='?'||wanted.back()=='+'||wanted.back()=='#'))wanted.pop_back();if(wanted.find("0-0")!=std::string::npos){std::replace(wanted.begin(),wanted.end(),'0','O');}for(auto m:b.legalMoves()){std::string candidate=san(b,m);while(!candidate.empty()&&(candidate.back()=='+'||candidate.back()=='#'))candidate.pop_back();if(candidate==wanted)return m;}throw std::invalid_argument("Invalid or illegal SAN move: "+token);}
std::string exportPgn(const Board& start,const std::vector<Move>& moves,const std::string& result){std::ostringstream out;out<<"[Event \"RookForge game\"]\n[Site \"Local\"]\n[Date \"????.??.??\"]\n[Round \"-\"]\n[White \"White\"]\n[Black \"Black\"]\n[Result \""<<result<<"\"]\n";Board b=start;if(start.fen()!=Board{}.fen())out<<"[SetUp \"1\"]\n[FEN \""<<start.fen()<<"\"]\n";out<<'\n';for(std::size_t i=0;i<moves.size();++i){if(b.turn()==Color::White)out<<b.fen().substr(b.fen().rfind(' ')+1)<<". ";out<<san(b,moves[i])<<' ';Undo u;b.makeMove(moves[i],u);}out<<result<<'\n';return out.str();}
std::vector<Move> importPgn(Board& start,const std::string& pgn){std::istringstream lines(pgn);std::string line,movetext;while(std::getline(lines,line)){auto first=line.find_first_not_of(" \t\r");if(first==std::string::npos)continue;if(line[first]=='['){auto key=line.find("FEN");if(key!=std::string::npos){auto q1=line.find('\"',key),q2=q1==std::string::npos?q1:line.find('\"',q1+1);if(q1==std::string::npos||q2==std::string::npos)throw std::invalid_argument("Malformed PGN FEN tag");start=Board::fromFen(line.substr(q1+1,q2-q1-1));}continue;}movetext+=line;movetext+='\n';}std::string clean;int variation=0;bool brace=false,semicolon=false;for(char c:movetext){if(semicolon){if(c=='\n')semicolon=false;continue;}if(brace){if(c=='}')brace=false;continue;}if(c==';'){semicolon=true;continue;}if(c=='{'){brace=true;continue;}if(c=='('){++variation;continue;}if(c==')'){if(variation==0)throw std::invalid_argument("Unmatched PGN variation terminator");--variation;continue;}if(!variation)clean+=c;}if(brace||variation)throw std::invalid_argument("Unterminated PGN comment or variation");std::istringstream tokens(clean);std::string token;std::vector<Move> moves;while(tokens>>token){if(token=="1-0"||token=="0-1"||token=="1/2-1/2"||token=="*")break;auto dot=token.find('.');if(dot!=std::string::npos){token=token.substr(token.find_last_of('.')+1);if(token.empty())continue;}auto m=parseSan(start,token);Undo u;start.makeMove(m,u);moves.push_back(m);}return moves;}
}
